mapper.select:
SELECT id, user_id, ingredient_name, ban_type, use_yn, created_at
  FROM user_bans
 WHERE id = #{id}

mapper.update:
UPDATE user_bans
   SET use_yn = 'N'
 WHERE id = #{id}

mapper.select:
SELECT ingredient_name
  FROM user_bans
 WHERE user_id = #{userId}
   AND ban_type = #{banType}
   AND use_yn = 'Y'
 ORDER BY created_at, id
